650		res := runResolveCLI(t, badConfig, `{not json`)
651		if res.exitCode == 0 || len(res.stdout) != 0 {
652			t.Fatalf("got exit %d stdout %q, want non-zero exit and empty stdout", res.exitCode, res.stdout)
