13	func main() {
14		command := "demo"
15		if len(os.Args) > 1 {
16			command = os.Args[1]
17		}
18		switch command {
19		case "demo":
20			runDemo()
21		case "version":
22			fmt.Println("contractsentinel 0.1.0")
23		case "help", "-h", "--help":
24			usage()
25		case "resolve":
26			runResolve(os.Args[2:])
27		default:
28			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
29			usage()
30			os.Exit(2)
31		}
32	}
33	
34	func usage() {
35		fmt.Println("usage: contractsentinel <command> [arguments]")
36		fmt.Println()
37		fmt.Println("commands:")
38		fmt.Println("  demo                        run the built-in audit demo")
39		fmt.Println("  resolve <config-file>       resolve one JSON request (read from stdin)")
40		fmt.Println("                              against offline routes; no network connections")
41		fmt.Println("  version                     print the version")
42		fmt.Println("  help                        show this help")
43	}
44	
45	func runResolve(args []string) {
46		if len(args) != 1 {
47			fail(contractsentinel.Failure{Code: "invalid_usage",
48				Reason: "usage: contractsentinel resolve <config-file>"})
49		}
50	
51		configData, err := os.ReadFile(args[0])
52		if err != nil {
53			fail(contractsentinel.Failure{Code: "invalid_config",
54				Reason: fmt.Sprintf("cannot read config file %q: %v", args[0], err)})
55		}
56	
57		// Validate the whole configuration as soon as the config file has been
58		// read, before touching stdin. A config that the existing rules can prove
59		// invalid must fail immediately even if the requesting program keeps the
60		// stdin pipe open and never delivers a request; the failure must not wait
61		// for, or be masked by, a later stdin read error.
62		cfg, f := contractsentinel.ParseConfig(configData)
63		if f != nil {
64			fail(*f)
65		}
66	
67		// The config is usable, so now block until the one JSON request on stdin
68		// is complete. A temporarily empty pipe is not an empty request.
69		requestData, err := io.ReadAll(os.Stdin)
70		if err != nil {
71			fail(contractsentinel.Failure{Code: "invalid_request",
72				Reason: fmt.Sprintf("cannot read request from stdin: %v", err)})
73		}
74	
75		req, f := contractsentinel.ParseRequest(requestData)
76		if f != nil {
77			fail(*f)
78		}
79		resolution, f := contractsentinel.Resolve(cfg, req)
80		if f != nil {
81			fail(*f)
82		}
83	
84		// HTML escaping is disabled so a raw query such as "a=1&b=2" is emitted
85		// byte for byte instead of "&".
86		enc := json.NewEncoder(os.Stdout)
87		enc.SetEscapeHTML(false)
88		if err := enc.Encode(resolution); err != nil {
89			fail(contractsentinel.Failure{Code: "internal_error", Reason: err.Error()})
90		}
91	}
92	
93	// fail prints the error as JSON to stderr and exits non-zero; stdout is left
94	// untouched so no partial result is observable on failure.
95	func fail(f contractsentinel.Failure) {
96		enc := json.NewEncoder(os.Stderr)
97		enc.SetEscapeHTML(false)
98		_ = enc.Encode(f)
99		os.Exit(1)
100	}
101	
102	func runDemo() {
103		artifact := contractsentinel.Artifact{Name: "Vault", ABI: "[{\"name\":\"withdraw\"}]", Bytecode: "0x6080", Source: "Vault.sol"}
104		rules := []contractsentinel.Rule{
105			{ID: "reentrancy-guard", Kind: "static", Severity: "high", Invariant: "no-reentrant-withdraw"},
106			{ID: "access-control", Kind: "static", Severity: "medium", Invariant: "owner-only-withdraw", RequiresABI: true},
107			{ID: "invariant-preserved", Kind: "symbolic", Severity: "critical", Invariant: "balance-monotonic"},
108		}
109		invariants := map[string]bool{"no-reentrant-withdraw": false, "owner-only-withdraw": true, "balance-monotonic": false}
110		findings, err := contractsentinel.Run(artifact, rules, invariants)
111		if err != nil {
112			fmt.Println("audit refused:", err)
113			return
114		}
115		for _, finding := range findings {
116			fmt.Printf("rule=%s severity=%s invariant=%s evidence=%s\n", finding.Rule, finding.Severity, finding.Invariant, finding.Evidence)
117		}
118		fmt.Printf("artifact=%s rules=%d findings=%d\n", artifact.Name, len(rules), len(findings))
119	}
